using System.Text;
using System.Text.Json.Nodes;
using May.VpsDeploy.Core;
using May.VpsDeploy.Infrastructure;

internal sealed partial class BoundaryTests
{
    public void RunClientShareTests() { using var f = new Fixture(repository); ClientShareExperience(f); Console.WriteLine($"PASS: {assertions} share serialization, path, source and selection assertions; no clipboard or production connections."); }
    private void ClientShareExperience(Fixture f)
    {
        var scheme = ClientSchemes.New(f.Paths); var region = scheme["Layout"]!.Strings("region_groups")[0]; var key = ServerConfigurations.RandomKey(); var user = ServerConfigurations.RandomKey(); var publicKey = ServerConfigurations.RandomKey(32).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        var links = new[] { "ss://aes-128-gcm:p%3Aa%40ss%23%25%2F%2B%3F@192.0.2.20:20001#%E4%B8%AD%E6%96%87%20%2F%23%26%2B", "ss://2022-blake3-aes-128-gcm:" + Uri.EscapeDataString(key + ":" + user) + "@[2001:db8::20]:20002#SS2022", "anytls://p%3Aa%40ss%23%25%2F%2B%3F@example.test:443/?sni=tls.example.test&insecure=0#AnyTLS", "vless://" + Guid.NewGuid() + "@192.0.2.30:443?encryption=none&type=tcp&security=reality&flow=xtls-rprx-vision&sni=example.test&fp=firefox&pbk=" + publicKey + "&sid=abcd1234&alpn=h2%2Chttp%2F1.1#Reality" };
        ClientNodeImport.Apply(scheme, ClientNodeImport.Preview(string.Join('\n', links), scheme, region, "entry")); var nodes = scheme["Nodes"]!.AsArray().OfType<JsonObject>().ToArray(); Check(nodes.Length == 4, "share fixture import incomplete");
        var before = ArchiveStore.Fingerprint(scheme); var preview = ClientShareLinks.Preview(scheme); var selected = preview.Rows.Select(r => r.Id).ToArray();
        Check(preview.Ready && preview.Rows.All(r => r.Ready) && ArchiveStore.Fingerprint(scheme) == before && !string.Join('\n', preview.Rows).Contains("p:a@ss") && !preview.ToString()!.Contains("ss://"), "share preview mutates source or reveals links: " + string.Join("; ", preview.Rows.Select(r => r.Protocol + ":" + r.Ready + ":" + r.Message)));
        var text = ClientShareLinks.Generate(scheme, preview, selected, "Plain"); var encoded = ClientShareLinks.Generate(scheme, preview, selected.Reverse().ToArray(), "Base64");
        Check(Encoding.UTF8.GetString(Convert.FromBase64String(encoded)) == text && ClientSubscriptions.Decode(encoded).Trim() == text.Trim(), "share Base64 changed content or source ordering");
        var fresh = ClientSchemes.New(f.Paths); var parsed = ClientNodeImport.Preview(text, fresh, region, "entry"); Check(parsed.Accepted == 4 && parsed.Rows.All(r => r.Status == "Ready"), "generated sharing list cannot be reimported");
        foreach (var (original, restored) in nodes.Zip(parsed.Rows.Select(r => r.Node!))) Check(ClientNodeImport.ConnectionFingerprint(original) == ClientNodeImport.ConnectionFingerprint(restored), "share round trip lost native connection settings");
        var serialized2022 = text.Split('\n')[1]; Check(serialized2022.StartsWith("ss://2022-") && serialized2022.Contains("%3A") && serialized2022.Contains("@[2001:db8::20]:20002"), "SS2022 used Base64 userinfo or lost IPv6 authority/identity chain");
        Check(ClientShareLinks.Generate(scheme, preview, [selected[2]], "Plain").StartsWith("anytls://") && ClientShareLinks.Generate(scheme, preview, [selected[2]], "Plain").Split('\n', StringSplitOptions.RemoveEmptyEntries).Length == 1, "share subset silently included other credentials");
        Refuses(() => ClientShareLinks.Generate(scheme, preview, [], "Plain"), "empty sharing selection accepted"); Refuses(() => ClientShareLinks.Generate(scheme, preview, [selected[0], selected[0]], "Plain"), "duplicate sharing selection accepted"); Refuses(() => ClientShareLinks.Generate(scheme, preview, [Guid.NewGuid().ToString("N")], "Plain"), "unknown sharing selection accepted"); Refuses(() => ClientShareLinks.Generate(scheme, preview, selected, "JSON"), "unrecognized share format accepted");
        var unknownId = Guid.NewGuid().ToString("N"); var forged = new ClientSharePreview(preview.SchemeFingerprint, [new(unknownId, "foreign", "anytls", true, "")], []); Refuses(() => ClientShareLinks.Generate(scheme, forged, [unknownId], "Plain"), "modified preview bypassed actual-node membership");
        scheme["Name"] = "changed after preview"; Refuses(() => ClientShareLinks.Generate(scheme, preview, selected, "Plain"), "stale sharing preview accepted"); scheme["Name"] = "新方案";
        void Blocked(int index, Action<JsonObject> edit)
        {
            var draft = scheme.DeepClone().AsObject(); var node = nodes[index].DeepClone().AsObject(); edit(node); draft["Nodes"] = new JsonArray(node); var report = ClientShareLinks.Preview(draft);
            Check(report.Rows.Count == 1 && !report.Rows[0].Ready && !report.Rows[0].Message.Contains("p:a@ss") && !report.Rows[0].Message.Contains(publicKey), "unsupported native setting silently dropped or disclosed"); Refuses(() => ClientShareLinks.Generate(draft, report, [node.Text("Id")], "Plain"), "unrepresentable node was exported");
        }
        Blocked(0, n => { n["kind"] = "landing"; n["transit_group"] = region; }); Blocked(0, n => n["sing_box"]!["detour"] = "other-entry"); Blocked(0, n => n["clash"]!["dialer-proxy"] = "other-entry");
        Blocked(0, n => n["sing_box"]!["plugin"] = "foreign"); Blocked(0, n => n["sing_box"]!["udp_over_tcp"] = new JsonObject { ["enabled"] = true }); Blocked(0, n => n["clash"]!["udp"] = false); Blocked(0, n => n["sing_box"]!["server_port"] = "443"); Blocked(0, n => n["sing_box"]!["password"] = "different");
        Blocked(2, n => n["sing_box"]!["tls"]!["ech"] = new JsonObject { ["enabled"] = true, ["config"] = new JsonArray("private-ech") }); Blocked(2, n => n["sing_box"]!["tls"]!["min_version"] = "1.3"); Blocked(2, n => n["sing_box"]!["tls"]!["certificate_path"] = "private.pem"); Blocked(2, n => n["sing_box"]!["tls"]!["insecure"] = true);
        Blocked(3, n => n["sing_box"]!["tls"]!["utls"]!["enabled"] = false); Blocked(3, n => n["sing_box"]!["tls"]!["reality"]!["public_key"] = "bad-key"); Blocked(3, n => n["sing_box"]!["tls"]!["alpn"] = new JsonArray("h2,other")); Blocked(3, n => n["sing_box"]!["transport"] = new JsonObject { ["type"] = "ws" });
        var single = scheme.DeepClone().AsObject(); single["Nodes"] = new JsonArray(nodes[0].DeepClone()); single["Nodes"]![0]!.AsObject().Remove("sing_box"); Check(ClientShareLinks.Preview(single).Ready, "Clash-only representable node cannot be shared");
        single = scheme.DeepClone().AsObject(); single["Nodes"] = new JsonArray(nodes[0].DeepClone()); single["Nodes"]![0]!.AsObject().Remove("clash"); Check(ClientShareLinks.Preview(single).Ready, "sing-box-only node cannot be shared");
        var processing = ClientOutputRules.New(); processing["Enabled"] = true; processing["Exclude"] = "AnyTLS"; processing["Prefix"] = "Public "; processing["Sort"] = "NameDescending"; scheme["OutputRules"] = processing; var outputPreview = ClientShareLinks.Preview(scheme);
        var outputText = ClientShareLinks.Generate(scheme, outputPreview, outputPreview.Rows.Select(r => r.Id).ToArray(), "Plain"); var names = ClientNodeImport.Preview(outputText, fresh, region, "entry").Rows.Select(r => r.Node!.Text("name")).ToArray(); Check(names.Length == 3 && names.All(n => n.StartsWith("Public ")) && names.SequenceEqual(names.OrderDescending(StringComparer.Ordinal)), "share output ignored filtering, renaming or order"); Check(nodes[0].Text("name").StartsWith("中文"), "share output renamed source node");
        var exporter = new ClientShareExport(f.Store); var directory = f.Paths.Resolve("share-exports"); Directory.CreateDirectory(directory); var target = Path.Combine(directory, "nodes.txt"); exporter.SaveNew(scheme, outputPreview, outputPreview.Rows.Select(r => r.Id).ToArray(), "Plain", target); Check(File.ReadAllText(target) == outputText && Directory.GetFiles(directory, "*.tmp").Length == 0, "share file publication not exact or left partial material");
        Refuses(() => exporter.SaveNew(scheme, outputPreview, outputPreview.Rows.Select(r => r.Id).ToArray(), "Plain", target), "share overwrote an existing file"); Refuses(() => exporter.SaveNew(scheme, outputPreview, outputPreview.Rows.Select(r => r.Id).ToArray(), "Plain", f.Paths.Resolve("config/foreign.txt")), "share wrote into application config"); Refuses(() => exporter.SaveNew(scheme, outputPreview, outputPreview.Rows.Select(r => r.Id).ToArray(), "Plain", Path.Combine(directory, "wrong.json")), "share disguised credential list as JSON"); Check(File.ReadAllText(target) == outputText, "failed sharing export damaged previous file");
        var managedPlan = f.Plan("Share-managed"); f.SaveInstance(managedPlan); var stateFile = SafePath.Resolve(f.Paths.Instance(f.Relative(managedPlan)), "deployment-state.json"); var state = ArchiveStore.ReadJson(stateFile); state.Put("Modules.deployment-commit.Status", JsonValue.Create("Success")); ArchiveStore.WriteJson(stateFile, state); var secrets = Fixture.RealitySecrets(); secrets.Put("Xray.RealityClientKey", JsonValue.Create(publicKey)); var secretFile = SafePath.Resolve(f.Paths.Instance(f.Relative(managedPlan)), "secrets.dotnet.private.json"); f.Store.WriteSecret(secretFile, secrets); var pair = ClientProfiles.Nodes(managedPlan, secrets).First();
        var managed = ClientSchemes.New(f.Paths); managed["Nodes"] = new JsonArray(new JsonObject { ["Id"] = Guid.NewGuid().ToString("N"), ["name"] = pair.Name, ["kind"] = "entry", ["region_group"] = region, ["sing_box"] = pair.SingBox.DeepClone(), ["clash"] = pair.Clash.DeepClone(), ["ManagedOrigin"] = ManagedNodeSources.Origin(f.Relative(managedPlan), pair), ["ServerRoute"] = new JsonObject { ["Name"] = "default landing" } });
        var managedPreview = ClientShareLinks.Preview(managed); Check(managedPreview.Ready && managedPreview.Rows[0].Message.Contains("服务器当前配置") && exporter.Generate(managed, managedPreview, [managedPreview.Rows[0].Id], "Plain").StartsWith("vless://"), "server-side route was confused with client detour");
        secrets.Put("Xray.Uuid", JsonValue.Create(Guid.NewGuid().ToString())); f.Store.WriteSecret(secretFile, secrets); Refuses(() => exporter.Generate(managed, managedPreview, [managedPreview.Rows[0].Id], "Plain"), "sharing exported stale managed credentials");
        var tooMany = ClientSchemes.New(f.Paths); tooMany["Nodes"] = new JsonArray(Enumerable.Range(0, 201).Select(i => { var n = nodes[0].DeepClone().AsObject(); n["Id"] = Guid.NewGuid().ToString("N"); return (JsonNode?)n; }).ToArray()); Refuses(() => ClientShareLinks.Preview(tooMany), "unbounded sharing list accepted");
        var duplicate = ClientSchemes.New(f.Paths); duplicate["Nodes"] = new JsonArray(nodes[0].DeepClone(), nodes[0].DeepClone()); Refuses(() => ClientShareLinks.Preview(duplicate), "ambiguous sharing identities accepted");
    }
}
